## 三、中断系统

### 3.1 外部中断配置

#### 3.1.1 外部中断原理

STM32的外部中断（EXTI）具有以下特点：
- **中断线**：19条外部中断线（EXTI0-EXTI18）
- **触发方式**：上升沿、下降沿、双边沿触发
- **优先级**：支持16级可编程优先级
- **中断嵌套**：支持中断嵌套

#### 3.1.2 外部中断配置

```c
#include "stm32f10x.h"  // 包含STM32F10x头文件

void GPIO初始化(void)  // GPIO初始化函数
{
    GPIO_InitTypeDef GPIO配置结构体 = {0};  // 定义GPIO配置结构体

    RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA | RCC_APB2Periph_AFIO, ENABLE);  
    // 开启GPIOA和AFIO时钟
    // 外部中断需要AFIO时钟

    // 配置GPIOA的Pin0为上拉输入（按键）
    GPIO配置结构体.GPIO_Pin = GPIO_Pin_0;           // 选择Pin0
    GPIO配置结构体.GPIO_Mode = GPIO_Mode_IPU;       // 上拉输入模式

    GPIO_Init(GPIOA, &GPIO配置结构体);  // 初始化GPIOA
}

void 外部中断初始化(void)  // 外部中断初始化函数
{
    EXTI_InitTypeDef 外部中断配置结构体 = {0};  // 定义外部中断配置结构体
    NVIC_InitTypeDef NVIC配置结构体 = {0};  // 定义NVIC配置结构体

    // 连接EXTI线到GPIO引脚
    GPIO_EXTILineConfig(GPIO_PortSourceGPIOA, GPIO_PinSource0);  
    // GPIO_EXTILineConfig：将EXTI线连接到GPIO引脚
    // GPIO_PortSourceGPIOA：GPIOA端口
    // GPIO_PinSource0：Pin0引脚
    // 将EXTI0线连接到GPIOA的Pin0

    // 配置外部中断线
    外部中断配置结构体.EXTI_Line = EXTI_Line0;  // 选择EXTI0线
    // EXTI_Line0：外部中断线0

    外部中断配置结构体.EXTI_Mode = EXTI_Mode_Interrupt;  // 中断模式
    // EXTI_Mode_Interrupt：中断模式
    // EXTI_Mode_Event：事件模式

    外部中断配置结构体.EXTI_Trigger = EXTI_Trigger_Falling;  // 下降沿触发
    // EXTI_Trigger_Falling：下降沿触发
    // EXTI_Trigger_Rising：上升沿触发
    // EXTI_Trigger_Rising_Falling：双边沿触发

    外部中断配置结构体.EXTI_LineCmd = ENABLE;  // 使能EXTI线
    // ENABLE：使能，DISABLE：失能

    EXTI_Init(&外部中断配置结构体);  // 初始化外部中断

    // 配置NVIC
    NVIC配置结构体.NVIC_IRQChannel = EXTI0_IRQn;  // 选择EXTI0中断通道
    // EXTI0_IRQn：EXTI0中断通道

    NVIC配置结构体.NVIC_IRQChannelPreemptionPriority = 1;  // 抢占优先级
    // NVIC_IRQChannelPreemptionPriority：抢占优先级
    // 抢占优先级：可以打断低优先级中断

    NVIC配置结构体.NVIC_IRQChannelSubPriority = 1;  // 响应优先级
    // NVIC_IRQChannelSubPriority：响应优先级
    // 响应优先级：抢占优先级相同时的优先级

    NVIC配置结构体.NVIC_IRQChannelCmd = ENABLE;  // 使能中断通道
    // ENABLE：使能，DISABLE：失能

    NVIC_Init(&NVIC配置结构体);  // 初始化NVIC
}

void EXTI0_IRQHandler(void)  // EXTI0中断服务函数
{
    if(EXTI_GetITStatus(EXTI_Line0) != RESET)  // 判断EXTI0中断标志
    // EXTI_GetITStatus：获取EXTI中断标志
    // EXTI_Line0：EXTI0线
    // != RESET：中断标志置位
    {
        // 中断处理代码
        // 例如：LED状态取反

        EXTI_ClearITPendingBit(EXTI_Line0);  // 清除EXTI0中断标志
        // EXTI_ClearITPendingBit：清除EXTI中断标志
        // EXTI_Line0：EXTI0线
        // 必须清除中断标志，否则会一直进入中断
    }
}

int main(void)  // 主函数
{
    GPIO初始化();  // 初始化GPIO
    外部中断初始化();  // 初始化外部中断

    while(1)  // 无限循环
    {
        // 主循环
        // 外部中断独立运行
    }
}
```

### 3.2 中断优先级

#### 3.2.1 优先级原理

STM32的中断优先级分为抢占优先级和响应优先级：
- **抢占优先级**：可以打断低优先级中断
- **响应优先级**：抢占优先级相同时的优先级
- **数值越小**：优先级越高

#### 3.2.2 多中断应用

```c
#include "stm32f10x.h"  // 包含STM32F10x头文件

void GPIO初始化(void)  // GPIO初始化函数
{
    GPIO_InitTypeDef GPIO配置结构体 = {0};  // 定义GPIO配置结构体

    RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA | RCC_APB2Periph_AFIO, ENABLE);  
    // 开启GPIOA和AFIO时钟

    // 配置GPIOA的Pin0为上拉输入（按键1）
    GPIO配置结构体.GPIO_Pin = GPIO_Pin_0;           
    GPIO配置结构体.GPIO_Mode = GPIO_Mode_IPU;       

    GPIO_Init(GPIOA, &GPIO配置结构体);  // 初始化GPIOA

    // 配置GPIOA的Pin1为上拉输入（按键2）
    GPIO配置结构体.GPIO_Pin = GPIO_Pin_1;           

    GPIO_Init(GPIOA, &GPIO配置结构体);  // 初始化GPIOA
}

void 外部中断初始化(void)  // 外部中断初始化函数
{
    EXTI_InitTypeDef 外部中断配置结构体 = {0};  // 定义外部中断配置结构体
    NVIC_InitTypeDef NVIC配置结构体 = {0};  // 定义NVIC配置结构体

    // 连接EXTI线到GPIO引脚
    GPIO_EXTILineConfig(GPIO_PortSourceGPIOA, GPIO_PinSource0);  
    // 将EXTI0线连接到GPIOA的Pin0

    GPIO_EXTILineConfig(GPIO_PortSourceGPIOA, GPIO_PinSource1);  
    // 将EXTI1线连接到GPIOA的Pin1

    // 配置EXTI0线
    外部中断配置结构体.EXTI_Line = EXTI_Line0;  
    外部中断配置结构体.EXTI_Mode = EXTI_Mode_Interrupt;  
    外部中断配置结构体.EXTI_Trigger = EXTI_Trigger_Falling;  
    外部中断配置结构体.EXTI_LineCmd = ENABLE;  

    EXTI_Init(&外部中断配置结构体);  // 初始化EXTI0

    // 配置EXTI1线
    外部中断配置结构体.EXTI_Line = EXTI_Line1;  

    EXTI_Init(&外部中断配置结构体);  // 初始化EXTI1

    // 配置NVIC（EXTI0高优先级）
    NVIC配置结构体.NVIC_IRQChannel = EXTI0_IRQn;  
    NVIC配置结构体.NVIC_IRQChannelPreemptionPriority = 0;  // 抢占优先级0
    NVIC配置结构体.NVIC_IRQChannelSubPriority = 0;  // 响应优先级0
    NVIC配置结构体.NVIC_IRQChannelCmd = ENABLE;  

    NVIC_Init(&NVIC配置结构体);  // 初始化NVIC（EXTI0）

    // 配置NVIC（EXTI1低优先级）
    NVIC配置结构体.NVIC_IRQChannel = EXTI1_IRQn;  
    NVIC配置结构体.NVIC_IRQChannelPreemptionPriority = 1;  // 抢占优先级1
    NVIC配置结构体.NVIC_IRQChannelSubPriority = 0;  // 响应优先级0
    NVIC配置结构体.NVIC_IRQChannelCmd = ENABLE;  

    NVIC_Init(&NVIC配置结构体);  // 初始化NVIC（EXTI1）
}

void EXTI0_IRQHandler(void)  // EXTI0中断服务函数（高优先级）
{
    if(EXTI_GetITStatus(EXTI_Line0) != RESET)  
    {
        // 中断处理代码
        // EXTI0可以打断EXTI1中断

        EXTI_ClearITPendingBit(EXTI_Line0);  // 清除中断标志
    }
}

void EXTI1_IRQHandler(void)  // EXTI1中断服务函数（低优先级）
{
    if(EXTI_GetITStatus(EXTI_Line1) != RESET)  
    {
        // 中断处理代码
        // EXTI1可以被EXTI0打断

        EXTI_ClearITPendingBit(EXTI_Line1);  // 清除中断标志
    }
}

int main(void)  // 主函数
{
    GPIO初始化();  // 初始化GPIO
    外部中断初始化();  // 初始化外部中断

    while(1)  // 无限循环
    {
        // 主循环
    }
}
```

