## 四、定时器应用

### 4.1 基本定时器

#### 4.1.1 基本定时器原理

STM32的基本定时器（TIM6、TIM7）具有以下特点：
- **16位计数器**：只能向上计数
- **无输入输出**：没有GPIO引脚
- **主要用途**：定时中断、DAC触发

#### 4.1.2 基本定时器配置

```c
#include "stm32f10x.h"  // 包含STM32F10x头文件

void 基本定时器初始化(void)  // 基本定时器初始化函数
{
    TIM_TimeBaseInitTypeDef 定时器配置结构体 = {0};  // 定义定时器配置结构体
    NVIC_InitTypeDef NVIC配置结构体 = {0};  // 定义NVIC配置结构体

    RCC_APB1PeriphClockCmd(RCC_APB1Periph_TIM6, ENABLE);  
    // 开启TIM6时钟
    // TIM6：基本定时器6，连接在APB1总线上

    // 配置定时器6
    定时器配置结构体.TIM_Period = 9999;  // 自动重装载值
    // 9999：计数从0到9999，共10000次
    // 定时时间 = 10000 × (1/72MHz) = 138.9μs

    定时器配置结构体.TIM_Prescaler = 7199;  // 预分频值
    // 7199：预分频系数为7200，系统时钟72MHz / 7200 = 10kHz
    // 定时器时钟 = 10kHz

    定时器配置结构体.TIM_ClockDivision = TIM_CKD_DIV1;  // 时钟分频

    定时器配置结构体.TIM_CounterMode = TIM_CounterMode_Up;  // 向上计数模式

    TIM_TimeBaseInit(TIM6, &定时器配置结构体);  // 初始化定时器6

    // 配置NVIC
    NVIC配置结构体.NVIC_IRQChannel = TIM6_IRQn;  // TIM6中断通道
    NVIC配置结构体.NVIC_IRQChannelPreemptionPriority = 0;  // 抢占优先级0
    NVIC配置结构体.NVIC_IRQChannelSubPriority = 0;  // 响应优先级0
    NVIC配置结构体.NVIC_IRQChannelCmd = ENABLE;  // 使能中断

    NVIC_Init(&NVIC配置结构体);  // 初始化NVIC

    TIM_ITConfig(TIM6, TIM_IT_Update, ENABLE);  // 使能TIM6更新中断
    // TIM_ITConfig：使能或失能定时器中断
    // TIM6：定时器6
    // TIM_IT_Update：更新中断
    // ENABLE：使能

    TIM_Cmd(TIM6, ENABLE);  // 使能定时器6
}

void TIM6_IRQHandler(void)  // TIM6中断服务函数
{
    if(TIM_GetITStatus(TIM6, TIM_IT_Update) != RESET)  // 判断TIM6更新中断标志
    // TIM_GetITStatus：获取定时器中断标志
    // TIM6：定时器6
    // TIM_IT_Update：更新中断
    {
        // 中断处理代码
        // 每1ms执行一次（10kHz / 10000 = 1Hz）

        TIM_ClearITPendingBit(TIM6, TIM_IT_Update);  // 清除TIM6更新中断标志
        // TIM_ClearITPendingBit：清除定时器中断标志
    }
}

int main(void)  // 主函数
{
    基本定时器初始化();  // 初始化基本定时器

    while(1)  // 无限循环
    {
        // 主循环
        // 定时器中断独立运行
    }
}
```

### 4.2 通用定时器

#### 4.2.1 通用定时器原理

STM32的通用定时器（TIM2-TIM5）具有以下特点：
- **16位计数器**：可以向上、向下、中央对齐计数
- **4个通道**：支持输入捕获、输出比较、PWM
- **多种功能**：编码器接口、门控模式等

#### 4.2.2 通用定时器配置

```c
#include "stm32f10x.h"  // 包含STM32F10x头文件

void 通用定时器初始化(void)  // 通用定时器初始化函数
{
    TIM_TimeBaseInitTypeDef 定时器配置结构体 = {0};  // 定义定时器配置结构体

    RCC_APB1PeriphClockCmd(RCC_APB1Periph_TIM2, ENABLE);  
    // 开启TIM2时钟

    // 配置定时器2
    定时器配置结构体.TIM_Period = 999;  // 自动重装载值
    // 999：计数从0到999，共1000次

    定时器配置结构体.TIM_Prescaler = 71;  // 预分频值
    // 71：预分频系数为72，系统时钟72MHz / 72 = 1MHz

    定时器配置结构体.TIM_ClockDivision = TIM_CKD_DIV1;  // 时钟分频

    定时器配置结构体.TIM_CounterMode = TIM_CounterMode_Up;  // 向上计数模式

    TIM_TimeBaseInit(TIM2, &定时器配置结构体);  // 初始化定时器2

    TIM_Cmd(TIM2, ENABLE);  // 使能定时器2
}

int main(void)  // 主函数
{
    通用定时器初始化();  // 初始化通用定时器

    while(1)  // 无限循环
    {
        // 主循环
        // 可以读取定时器计数值
        uint16_t 计数值 = TIM_GetCounter(TIM2);  // 读取定时器2计数值
        // TIM_GetCounter：获取定时器计数值
        // TIM2：定时器2
    }
}
