## 五、串口通信

### 5.1 USART配置

#### 5.1.1 USART原理

STM32的USART（通用同步/异步收发器）具有以下特点：
- **全双工**：同时发送和接收
- **可配置**：数据位、停止位、校验位可配置
- **DMA支持**：支持DMA传输
- **多种模式**：同步、异步、智能卡、IrDA等

#### 5.1.2 USART初始化

```c
#include "stm32f10x.h"  // 包含STM32F10x头文件

void USART初始化(uint32_t 波特率)  // USART初始化函数
{
    GPIO_InitTypeDef GPIO配置结构体 = {0};  // 定义GPIO配置结构体
    USART_InitTypeDef USART配置结构体 = {0};  // 定义USART配置结构体

    // 开启时钟
    RCC_APB2PeriphClockCmd(RCC_APB2Periph_USART1 | RCC_APB2Periph_GPIOA, ENABLE);  
    // 开启USART1和GPIOA时钟
    // USART1连接在APB2总线上

    // 配置GPIOA的Pin9为复用推挽输出（USART1_TX）
    GPIO配置结构体.GPIO_Pin = GPIO_Pin_9;           // 选择Pin9
    GPIO配置结构体.GPIO_Mode = GPIO_Mode_AF_PP;     // 复用推挽输出模式
    GPIO配置结构体.GPIO_Speed = GPIO_Speed_50MHz;    // 输出速度50MHz

    GPIO_Init(GPIOA, &GPIO配置结构体);  // 初始化GPIOA

    // 配置GPIOA的Pin10为浮空输入（USART1_RX）
    GPIO配置结构体.GPIO_Pin = GPIO_Pin_10;          // 选择Pin10
    GPIO配置结构体.GPIO_Mode = GPIO_Mode_IN_FLOATING;  // 浮空输入模式
    // GPIO_Mode_IN_FLOATING：浮空输入模式

    GPIO_Init(GPIOA, &GPIO配置结构体);  // 初始化GPIOA

    // 配置USART1
    USART配置结构体.USART_BaudRate = 波特率;  // 波特率
    // USART_BaudRate：波特率
    // 常用波特率：9600、19200、38400、57600、115200

    USART配置结构体.USART_WordLength = USART_WordLength_8b;  // 数据位8位
    // USART_WordLength_8b：8位数据位

    USART配置结构体.USART_StopBits = USART_StopBits_1;  // 停止位1位
    // USART_StopBits_1：1位停止位

    USART配置结构体.USART_Parity = USART_Parity_No;  // 无校验
    // USART_Parity_No：无校验
    // USART_Parity_Even：偶校验
    // USART_Parity_Odd：奇校验

    USART配置结构体.USART_Mode = USART_Mode_Rx | USART_Mode_Tx;  // 收发模式
    // USART_Mode_Rx：接收模式
    // USART_Mode_Tx：发送模式

    USART配置结构体.USART_HardwareFlowControl = USART_HardwareFlowControl_None;  
    // 无硬件流控

    USART_Init(USART1, &USART配置结构体);  // 初始化USART1

    USART_Cmd(USART1, ENABLE);  // 使能USART1
}

void USART发送字符(uint8_t 字符)  // USART发送字符函数
{
    USART_SendData(USART1, 字符);  // 发送字符
    // USART_SendData：发送数据
    // USART1：USART1
    // 字符：要发送的字符

    while(USART_GetFlagStatus(USART1, USART_FLAG_TXE) == RESET);  
    // 等待发送完成
    // USART_GetFlagStatus：获取USART标志
    // USART1：USART1
    // USART_FLAG_TXE：发送数据寄存器空标志
    // == RESET：等待标志置位
}

uint8_t USART接收字符(void)  // USART接收字符函数
{
    while(USART_GetFlagStatus(USART1, USART_FLAG_RXNE) == RESET);  
    // 等待接收完成
    // USART_FLAG_RXNE：接收数据寄存器非空标志

    return USART_ReceiveData(USART1);  // 返回接收到的字符
    // USART_ReceiveData：接收数据
}

int main(void)  // 主函数
{
    USART初始化(9600);  // 初始化USART，波特率9600

    while(1)  // 无限循环
    {
        USART发送字符('A');  // 发送字符'A'
        // 调用USART发送字符函数

        uint8_t 接收字符 = USART接收字符();  // 接收字符
        // 调用USART接收字符函数
    }
}
```

