## 六、显示模块

### 6.1 OLED显示

#### 6.1.1 OLED原理

OLED（有机发光二极管）是一种新型显示技术：
- **自发光**：无需背光，对比度高
- **功耗低**：相比LCD功耗更低
- **接口**：I2C或SPI接口

#### 6.1.2 OLED初始化和显示

```c
#include "stm32f10x.h"  // 包含STM32F10x头文件
#include "i2c.h"  // 包含I2C驱动头文件

void I2C初始化(void)  // I2C初始化函数
{
    GPIO_InitTypeDef GPIO配置结构体 = {0};  // 定义GPIO配置结构体
    I2C_InitTypeDef I2C配置结构体 = {0};  // 定义I2C配置结构体

    // 开启时钟
    RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOB, ENABLE);  // 开启GPIOB时钟
    RCC_APB1PeriphClockCmd(RCC_APB1Periph_I2C1, ENABLE);  // 开启I2C1时钟

    // 配置GPIOB的Pin6（SCL）和Pin7（SDA）为复用开漏输出
    GPIO配置结构体.GPIO_Pin = GPIO_Pin_6 | GPIO_Pin_7;  // 选择Pin6和Pin7
    GPIO配置结构体.GPIO_Mode = GPIO_Mode_AF_OD;  // 复用开漏输出模式
    // GPIO_Mode_AF_OD：复用开漏输出模式
    // 开漏输出：用于I2C通信

    GPIO配置结构体.GPIO_Speed = GPIO_Speed_50MHz;  // 输出速度50MHz

    GPIO_Init(GPIOB, &GPIO配置结构体);  // 初始化GPIOB

    // 配置I2C1
    I2C配置结构体.I2C_Mode = I2C_Mode_I2C;  // I2C模式
    // I2C_Mode_I2C：I2C模式

    I2C配置结构体.I2C_DutyCycle = I2C_DutyCycle_2;  // I2C占空比
    // I2C_DutyCycle_2：I2C占空比为2

    I2C配置结构体.I2C_OwnAddress1 = 0x00;  // 自身地址1
    // I2C_OwnAddress1：I2C自身地址1
    // 0x00：不使用自身地址

    I2C配置结构体.I2C_Ack = I2C_Ack_Enable;  // 使能应答
    // I2C_Ack_Enable：使能应答

    I2C配置结构体.I2C_AcknowledgedAddress = I2C_AcknowledgedAddress_7bit;  // 7位地址
    // I2C_AcknowledgedAddress_7bit：7位地址模式

    I2C配置结构体.I2C_ClockSpeed = 100000;  // 时钟速度100kHz
    // I2C_ClockSpeed：I2C时钟速度
    // 100000：100kHz

    I2C_Init(I2C1, &I2C配置结构体);  // 初始化I2C1

    I2C_Cmd(I2C1, ENABLE);  // 使能I2C1
}

void OLED写命令(uint8_t 命令)  // OLED写命令函数
{
    I2C_GenerateSTART(I2C1, ENABLE);  // 产生I2C起始信号
    // I2C_GenerateSTART：产生I2C起始信号
    // I2C1：I2C1
    // ENABLE：使能

    while(!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_MODE_SELECT));  
    // 等待主模式选择事件
    // I2C_CheckEvent：检查I2C事件
    // I2C_EVENT_MASTER_MODE_SELECT：主模式选择事件

    I2C_SendData(I2C1, 0x78);  // 发送OLED地址
    // I2C_SendData：发送数据
    // 0x78：OLED地址

    while(!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_TRANSMITTER_MODE_SELECTED));  
    // 等待主发送模式选择事件

    I2C_SendData(I2C1, 0x00);  // 发送命令标志
    // 0x00：命令标志

    while(!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_BYTE_TRANSMITTED));  
    // 等待主字节发送完成事件

    I2C_SendData(I2C1, 命令);  // 发送命令

    while(!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_BYTE_TRANSMITTED));  
    // 等待主字节发送完成事件

    I2C_GenerateSTOP(I2C1, ENABLE);  // 产生I2C停止信号
    // I2C_GenerateSTOP：产生I2C停止信号
}

void OLED写数据(uint8_t 数据)  // OLED写数据函数
{
    I2C_GenerateSTART(I2C1, ENABLE);  // 产生I2C起始信号

    while(!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_MODE_SELECT));  
    // 等待主模式选择事件

    I2C_SendData(I2C1, 0x78);  // 发送OLED地址

    while(!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_TRANSMITTER_MODE_SELECTED));  
    // 等待主发送模式选择事件

    I2C_SendData(I2C1, 0x40);  // 发送数据标志
    // 0x40：数据标志

    while(!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_BYTE_TRANSMITTED));  
    // 等待主字节发送完成事件

    I2C_SendData(I2C1, 数据);  // 发送数据

    while(!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_BYTE_TRANSMITTED));  
    // 等待主字节发送完成事件

    I2C_GenerateSTOP(I2C1, ENABLE);  // 产生I2C停止信号
}

void OLED初始化(void)  // OLED初始化函数
{
    延时(100000);  // 等待OLED上电稳定

    OLED写命令(0xAE);  // 关闭显示
    OLED写命令(0xD5);  // 设置时钟分频因子
    OLED写命令(0x80);  // 建议值
    OLED写命令(0xA8);  // 设置驱动路数
    OLED写命令(0x3F);  // 默认0X3F(1/64)
    OLED写命令(0xD3);  // 设置显示偏移
    OLED写命令(0x00);  // 默认为0
    OLED写命令(0x40);  // 设置显示开始行
    OLED写命令(0x8D);  // 电荷泵设置
    OLED写命令(0x14);  // 开启电荷泵
    OLED写命令(0x20);  // 设置内存地址模式
    OLED写命令(0x02);  // 页地址模式
    OLED写命令(0xA1);  // 段重定向设置
    OLED写命令(0xC8);  // 设置COM扫描方向
    OLED写命令(0xDA);  // 设置COM硬件引脚配置
    OLED写命令(0x12);  // 默认值
    OLED写命令(0x81);  // 对比度设置
    OLED写命令(0xCF);  // 默认值
    OLED写命令(0xD9);  // 设置预充电周期
    OLED写命令(0xF1);  // 默认值
    OLED写命令(0xDB);  // 设置VCOMH电压倍率
    OLED写命令(0x40);  // 默认值
    OLED写命令(0xA4);  // 全局显示开启
    OLED写命令(0xA6);  // 设置显示方式
    OLED写命令(0xAF);  // 开启显示
}

void OLED清屏(void)  // OLED清屏函数
{
    uint8_t 页, 列;  // 定义页和列变量

    for(页 = 0; 页 < 8; 页++)  // 循环8页
    {
        OLED写命令(0xB0 + 页);  // 设置页地址
        OLED写命令(0x00);  // 设置列地址低4位
        OLED写命令(0x10);  // 设置列地址高4位

        for(列 = 0; 列 < 128; 列++)  // 循环128列
        {
            OLED写数据(0x00);  // 写入0，清屏
        }
    }
}

void 延时(uint32_t 延时时间)  // 延时函数
{
    uint32_t 计数器;  // 定义计数器变量

    for(计数器 = 0; 计数器 < 延时时间; 计数器++)  // for循环
    {
        // 空循环
    }
}

int main(void)  // 主函数
{
    I2C初始化();  // 初始化I2C
    OLED初始化();  // 初始化OLED
    OLED清屏();  // 清屏

    while(1)  // 无限循环
    {
        // 主循环
    }
}
```

