## 七、传感器应用

### 7.1 温度传感器DS18B20

#### 7.1.1 DS18B20原理

DS18B20是一种数字温度传感器：
- **温度范围**：-55℃到+125℃
- **精度**：±0.5℃
- **接口**：单总线接口

#### 7.1.2 DS18B20温度读取

```c
#include "stm32f10x.h"  // 包含STM32F10x头文件

#define DS18B20_DQ_PIN GPIO_Pin_0  // DS18B20数据引脚
#define DS18B20_DQ_PORT GPIOA      // DS18B20数据端口

void DS18B20_DQ输出(void)  // DS18B20_DQ设置为输出
{
    GPIO_InitTypeDef GPIO配置结构体 = {0};  // 定义GPIO配置结构体

    GPIO配置结构体.GPIO_Pin = DS18B20_DQ_PIN;  // 选择DS18B20数据引脚
    GPIO配置结构体.GPIO_Mode = GPIO_Mode_Out_PP;  // 推挽输出模式
    GPIO配置结构体.GPIO_Speed = GPIO_Speed_50MHz;  // 输出速度50MHz

    GPIO_Init(DS18B20_DQ_PORT, &GPIO配置结构体);  // 初始化GPIO
}

void DS18B20_DQ输入(void)  // DS18B20_DQ设置为输入
{
    GPIO_InitTypeDef GPIO配置结构体 = {0};  // 定义GPIO配置结构体

    GPIO配置结构体.GPIO_Pin = DS18B20_DQ_PIN;  // 选择DS18B20数据引脚
    GPIO配置结构体.GPIO_Mode = GPIO_Mode_IPU;  // 上拉输入模式

    GPIO_Init(DS18B20_DQ_PORT, &GPIO配置结构体);  // 初始化GPIO
}

void DS18B20复位(void)  // DS18B20复位函数
{
    DS18B20_DQ输出();  // 设置为输出

    GPIO_WriteBit(DS18B20_DQ_PORT, DS18B20_DQ_PIN, Bit_RESET);  // 数据线低电平
    延时(600);  // 延时480us以上

    GPIO_WriteBit(DS18B20_DQ_PORT, DS18B20_DQ_PIN, Bit_SET);  // 数据线高电平
    延时(100);  // 延时

    DS18B20_DQ输入();  // 设置为输入

    while(GPIO_ReadInputDataBit(DS18B20_DQ_PORT, DS18B20_DQ_PIN));  // 等待DS18B20响应
    while(!GPIO_ReadInputDataBit(DS18B20_DQ_PORT, DS18B20_DQ_PIN));  // 等待DS18B20释放
}

void DS18B20写字节(uint8_t 字节)  // DS18B20写字节函数
{
    uint8_t 位计数器;  // 定义位计数器

    DS18B20_DQ输出();  // 设置为输出

    for(位计数器 = 0; 位计数器 < 8; 位计数器++)  // 循环8位
    {
        GPIO_WriteBit(DS18B20_DQ_PORT, DS18B20_DQ_PIN, Bit_RESET);  // 数据线低电平
        延时(10);  // 延时

        if(字节 & 0x01)  // 判断最低位
        {
            GPIO_WriteBit(DS18B20_DQ_PORT, DS18B20_DQ_PIN, Bit_SET);  // 数据线高电平
        }

        延时(60);  // 延时
        GPIO_WriteBit(DS18B20_DQ_PORT, DS18B20_DQ_PIN, Bit_SET);  // 数据线高电平
        延时(10);  // 延时

        字节 >>= 1;  // 字节右移1位
    }
}

uint8_t DS18B20读字节(void)  // DS18B20读字节函数
{
    uint8_t 字节 = 0;  // 定义字节变量
    uint8_t 位计数器;  // 定义位计数器

    for(位计数器 = 0; 位计数器 < 8; 位计数器++)  // 循环8位
    {
        字节 >>= 1;  // 字节右移1位

        DS18B20_DQ输出();  // 设置为输出
        GPIO_WriteBit(DS18B20_DQ_PORT, DS18B20_DQ_PIN, Bit_RESET);  // 数据线低电平
        延时(10);  // 延时

        DS18B20_DQ输入();  // 设置为输入
        延时(10);  // 延时

        if(GPIO_ReadInputDataBit(DS18B20_DQ_PORT, DS18B20_DQ_PIN))  // 判断数据线状态
        {
            字节 |= 0x80;  // 设置最高位
        }

        延时(50);  // 延时
    }

    return 字节;  // 返回读取的字节
}

float DS18B20读取温度(void)  // DS18B20读取温度函数
{
    uint8_t 温度低8位;  // 定义温度低8位变量
    uint8_t 温度高8位;  // 定义温度高8位变量
    uint16_t 温度值;  // 定义温度值变量
    float 温度;  // 定义温度变量

    DS18B20复位();  // 复位DS18B20
    DS18B20写字节(0xCC);  // 跳过ROM
    DS18B20写字节(0x44);  // 启动温度转换

    延时(100000);  // 等待温度转换完成

    DS18B20复位();  // 复位DS18B20
    DS18B20写字节(0xCC);  // 跳过ROM
    DS18B20写字节(0xBE);  // 读取暂存器

    温度低8位 = DS18B20读字节();  // 读取温度低8位
    温度高8位 = DS18B20读字节();  // 读取温度高8位

    温度值 = (温度高8位 << 8) | 温度低8位;  // 组合温度值

    温度 = 温度值 * 0.0625;  // 计算温度值

    return 温度;  // 返回温度值
}

void 延时(uint32_t 延时时间)  // 延时函数
{
    uint32_t 计数器;  // 定义计数器变量

    for(计数器 = 0; 计数器 < 延时时间; 计数器++)  // for循环
    {
        // 空循环
    }
}

int main(void)  // 主函数
{
    float 当前温度;  // 定义当前温度变量

    while(1)  // 无限循环
    {
        当前温度 = DS18B20读取温度();  // 读取温度

        // 可以将温度值显示到OLED或串口
    }
}
```

