## 九、通信协议

### 9.1 I2C通信

#### 9.1.1 I2C通信原理

I2C（Inter-Integrated Circuit）是一种串行通信协议：
- **通信方式**：双线制（SDA数据线、SCL时钟线）
- **通信速率**：标准模式100kbps，快速模式400kbps
- **寻址方式**：7位地址或10位地址

#### 9.1.2 I2C通信代码

```c
#include "stm32f10x.h"  // 包含STM32F10x头文件

void I2C初始化(void)  // I2C初始化函数
{
    GPIO_InitTypeDef GPIO配置结构体 = {0};  // 定义GPIO配置结构体
    I2C_InitTypeDef I2C配置结构体 = {0};  // 定义I2C配置结构体

    // 开启时钟
    RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOB, ENABLE);  // 开启GPIOB时钟
    RCC_APB1PeriphClockCmd(RCC_APB1Periph_I2C1, ENABLE);  // 开启I2C1时钟

    // 配置GPIOB的Pin6（SCL）和Pin7（SDA）为复用开漏输出
    GPIO配置结构体.GPIO_Pin = GPIO_Pin_6 | GPIO_Pin_7;  // 选择Pin6和Pin7
    GPIO配置结构体.GPIO_Mode = GPIO_Mode_AF_OD;  // 复用开漏输出模式

    GPIO配置结构体.GPIO_Speed = GPIO_Speed_50MHz;  // 输出速度50MHz

    GPIO_Init(GPIOB, &GPIO配置结构体);  // 初始化GPIOB

    // 配置I2C1
    I2C配置结构体.I2C_Mode = I2C_Mode_I2C;  // I2C模式
    I2C配置结构体.I2C_DutyCycle = I2C_DutyCycle_2;  // I2C占空比
    I2C配置结构体.I2C_OwnAddress1 = 0x00;  // 自身地址1
    I2C配置结构体.I2C_Ack = I2C_Ack_Enable;  // 使能应答
    I2C配置结构体.I2C_AcknowledgedAddress = I2C_AcknowledgedAddress_7bit;  // 7位地址
    I2C配置结构体.I2C_ClockSpeed = 100000;  // 时钟速度100kHz

    I2C_Init(I2C1, &I2C配置结构体);  // 初始化I2C1

    I2C_Cmd(I2C1, ENABLE);  // 使能I2C1
}

void I2C写入数据(uint8_t 设备地址, uint8_t 寄存器地址, uint8_t 数据)  // I2C写入数据函数
{
    I2C_GenerateSTART(I2C1, ENABLE);  // 产生I2C起始信号

    while(!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_MODE_SELECT));  
    // 等待主模式选择事件

    I2C_SendData(I2C1, 设备地址 << 1);  // 发送设备地址（写）
    // 设备地址 << 1：左移1位，最低位为0表示写

    while(!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_TRANSMITTER_MODE_SELECTED));  
    // 等待主发送模式选择事件

    I2C_SendData(I2C1, 寄存器地址);  // 发送寄存器地址

    while(!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_BYTE_TRANSMITTED));  
    // 等待主字节发送完成事件

    I2C_SendData(I2C1, 数据);  // 发送数据

    while(!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_BYTE_TRANSMITTED));  
    // 等待主字节发送完成事件

    I2C_GenerateSTOP(I2C1, ENABLE);  // 产生I2C停止信号
}

uint8_t I2C读取数据(uint8_t 设备地址, uint8_t 寄存器地址)  // I2C读取数据函数
{
    uint8_t 数据;  // 定义数据变量

    I2C_GenerateSTART(I2C1, ENABLE);  // 产生I2C起始信号

    while(!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_MODE_SELECT));  
    // 等待主模式选择事件

    I2C_SendData(I2C1, 设备地址 << 1);  // 发送设备地址（写）

    while(!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_TRANSMITTER_MODE_SELECTED));  
    // 等待主发送模式选择事件

    I2C_SendData(I2C1, 寄存器地址);  // 发送寄存器地址

    while(!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_BYTE_TRANSMITTED));  
    // 等待主字节发送完成事件

    I2C_GenerateSTART(I2C1, ENABLE);  // 产生I2C起始信号

    while(!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_MODE_SELECT));  
    // 等待主模式选择事件

    I2C_SendData(I2C1, (设备地址 << 1) | 0x01);  // 发送设备地址（读）
    // (设备地址 << 1) | 0x01：左移1位后最低位置1，表示读

    while(!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_RECEIVER_MODE_SELECTED));  
    // 等待主接收模式选择事件

    数据 = I2C_ReceiveData(I2C1);  // 接收数据

    I2C_AcknowledgeConfig(I2C1, DISABLE);  // 发送非应答
    // I2C_AcknowledgeConfig：配置应答
    // DISABLE：非应答

    while(!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_BYTE_RECEIVED));  
    // 等待主字节接收完成事件

    I2C_GenerateSTOP(I2C1, ENABLE);  // 产生I2C停止信号

    return 数据;  // 返回读取的数据
}

int main(void)  // 主函数
{
    uint8_t 设备地址 = 0xA0;  // 定义设备地址
    uint8_t 寄存器地址 = 0x00;  // 定义寄存器地址
    uint8_t 写入数据 = 0x55;  // 定义写入数据
    uint8_t 读取数据;  // 定义读取数据

    I2C初始化();  // 初始化I2C

    I2C写入数据(设备地址, 寄存器地址, 写入数据);  // 写入数据

    读取数据 = I2C读取数据(设备地址, 寄存器地址);  // 读取数据

    while(1)  // 无限循环
    {
        // 主循环
    }
}
```

