- **温度显示**：使用OLED显示温度
- **温度控制**：使用继电器控制加热器
- **按键设置**：使用按键设置目标温度

#### 10.1.2 项目代码

```c
#include "stm32f10x.h"  // 包含STM32F10x头文件

// 定义变量
float 当前温度 = 0.0;  // 当前温度
float 目标温度 = 25.0;  // 目标温度
uint8_t 设置模式 = 0;  // 设置模式标志

void GPIO初始化(void)  // GPIO初始化函数
{
    GPIO_InitTypeDef GPIO配置结构体 = {0};  // 定义GPIO配置结构体

    RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA | RCC_APB2Periph_GPIOC, ENABLE);  
    // 开启GPIOA和GPIOC时钟

    // 配置GPIOA的Pin0为推挽输出（继电器）
    GPIO配置结构体.GPIO_Pin = GPIO_Pin_0;           
    GPIO配置结构体.GPIO_Mode = GPIO_Mode_Out_PP;     
    GPIO配置结构体.GPIO_Speed = GPIO_Speed_50MHz;    

    GPIO_Init(GPIOA, &GPIO配置结构体);  // 初始化GPIOA

    // 配置GPIOC的Pin13为上拉输入（设置按键）
    GPIO配置结构体.GPIO_Pin = GPIO_Pin_13;          
    GPIO配置结构体.GPIO_Mode = GPIO_Mode_IPU;       

    GPIO_Init(GPIOC, &GPIO配置结构体);  // 初始化GPIOC
}

void 延时(uint32_t 延时时间)  // 延时函数
{
    uint32_t 计数器;  // 定义计数器变量

    for(计数器 = 0; 计数器 < 延时时间; 计数器++)  // for循环
    {
        // 空循环
    }
}

void 按键处理(void)  // 按键处理函数
{
    static uint32_t 按键计数器 = 0;  // 静态变量，按键计数器
    static uint8_t 按键状态 = 1;  // 静态变量，按键状态

    if(GPIO_ReadInputDataBit(GPIOC, GPIO_Pin_13) == 0)  // 检测按键按下
    {
        按键计数器++;  // 按键计数器加1

        if(按键计数器 > 1000)  // 判断按键是否稳定
        {
            if(按键状态 == 1)  // 判断按键状态是否变化
            {
                按键状态 = 0;  // 更新按键状态
                设置模式 = ~设置模式;  // 切换设置模式
                // 设置模式取反
            }
        }
    }
    else  // 按键释放
    {
        按键计数器 = 0;  // 清零按键计数器
        按键状态 = 1;  // 更新按键状态
    }
}

void 温度控制(void)  // 温度控制函数
{
    if(当前温度 < 目标温度 - 1.0)  // 判断温度是否低于目标温度
    {
        GPIO_WriteBit(GPIOA, GPIO_Pin_0, Bit_RESET);  // 开启加热器
        // 温度低于目标温度时开启加热器
    }
    else if(当前温度 > 目标温度 + 1.0)  // 判断温度是否高于目标温度
    {
        GPIO_WriteBit(GPIOA, GPIO_Pin_0, Bit_SET);  // 关闭加热器
        // 温度高于目标温度时关闭加热器
    }
}

int main(void)  // 主函数
{
    GPIO初始化();  // 初始化GPIO

    GPIO_WriteBit(GPIOA, GPIO_Pin_0, Bit_SET);  // 继电器初始关闭

    while(1)  // 无限循环
    {
        当前温度 = DS18B20读取温度();  // 读取温度

        按键处理();  // 处理按键

        温度控制();  // 控制温度

        // 显示温度（这里只是示例，实际应用需要添加显示代码）

        延时(100000);  // 延时
    }
}
```

